describe('Date Picker - Prevent Past Dates for Future Bookings', () => {
  beforeEach(() => {
    cy.visit('/bookings');
  });

  it('should prevent selection of past dates when booking for a future date', () => {
    // Get the date picker input field
    cy.get('[data-testid="date-picker-input"]').should('be.visible');

    // Get the current date
    cy.get('[data-testid="current-date"]').then((currentDate) => {
      const currentDateString = currentDate.text().trim();
      const currentDateObj = cy.dateParser(currentDateString);
      const currentDate = new Date(currentDateObj);
    });

    // Get the future booking date
    cy.get('[data-testid="future-booking-date"]').should('be.visible');
    cy.get('[data-testid="future-booking-date"]').click();

    // Verify the date picker opens
    cy.get('[data-testid="date-picker-popup"]').should('be.visible');

    // Select a past date
    cy.get('[data-testid="date-picker-calendar"]').click();
    cy.get('[data-testid="day-cell-1999"]').click();

    // Verify the past date is highlighted
    cy.get('[data-testid="day-cell-1999"]').should('be.visible');

    // Verify the date picker does not allow selection
    cy.get('[data-testid="date-picker-input"]').should('not.have.value');

    // Verify the error message is displayed
    cy.get('[data-testid="date-picker-error-message"]').should('be.visible');
    cy.get('[data-testid="date-picker-error-message"]').should('contain', 'Cannot select past dates');

    // Verify the booking form is still visible
    cy.get('[data-testid="booking-form"]').should('be.visible');
  });

  it('should allow selection of future dates when booking for a future date', () => {
    // Get the current date
    cy.get('[data-testid="current-date"]').then((currentDate) => {
      const currentDateString = currentDate.text().trim();
      const currentDateObj = cy.dateParser(currentDateString);
      const currentDate = new Date(currentDateObj);
    });

    // Get the future booking date
    cy.get('[data-testid="future-booking-date"]').should('be.visible');
    cy.get('[data-testid="future-booking-date"]').click();

    // Verify the date picker opens
    cy.get('[data-testid="date-picker-popup"]').should('be.visible');

    // Select a future date
    cy.get('[data-testid="date-picker-calendar"]').click();
    cy.get('[data-testid="day-cell-2025"]').click();

    // Verify the future date is highlighted
    cy.get('[data-testid="day-cell-2025"]').should('be.visible');

    // Verify the date is selected
    cy.get('[data-testid="date-picker-input"]').should('have.value', '2025-01-01');

    // Verify the error message is not displayed
    cy.get('[data-testid="date-picker-error-message"]').should('not.exist');

    // Verify the booking form is still visible
    cy.get('[data-testid="booking-form"]').should('be.visible');
  });
});
